def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    percentage_increase = (change / v1) * 100

    return {
        "value": percentage_increase,
        "trace": {
            "starting_value": v1,
            "ending_value": v2,
            "change": change,
            "percentage_increase": percentage_increase,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "%"
            }
        }
    }
